function isHeavyEnemy(id){const e=enemyCatalog[id];return !!e&&(e.hp>=350||e.bossOnly);}
function waveRoster(planet,wave){const count=8+wave*3+planet-1,result=Array(count).fill('grunt');if(wave<=3)return result;const eligible=Object.entries(enemyCatalog).filter(([id,e])=>id!=='grunt'&&!e.bossOnly&&e.planet<=planet&&wave>=enemyWaveStages[id]),rng=random(900+planet*100+wave),share=[0,0,0,0,.18,.27,.35,.42,.48,.54,.60][wave],advanced=Math.round(count*share),total=eligible.reduce((sum,[id,e])=>sum+(e.weight||1),0);for(let j=0;j<advanced;j++){let weight=rng()*total;const id=eligible.find(([id,e])=>(weight-=(e.weight||1))<=0)?.[0]||'runner',slot=Math.min(count-1,Math.floor((j+.5)*count/advanced));result[slot]=id;}const first=Object.entries(enemyCatalog).filter(([,e])=>!e.bossOnly&&e.planet===planet&&e.wave===wave);const reserved=new Set();first.forEach(([id],j)=>{const slot=Math.floor((j+1)*count/(first.length+1));result[slot]=id;if(isHeavyEnemy(id))reserved.add(slot);});if(wave===10){result[count-1]=planet===10?'sovereign':planet===9?'leviathan':planet>=4?'broodmother':'boss';reserved.add(count-1);}const limit=wave>=8?2:1,keep=new Set(reserved),light=eligible.filter(([id])=>!isHeavyEnemy(id));for(let i=0;i<count;i++)if(isHeavyEnemy(result[i])&&!keep.has(i)){if(keep.size<limit)keep.add(i);else result[i]=light.length?light[Math.floor(rng()*light.length)][0]:'grunt';}return result;}

