function terrainValid(p){if(window.Art?.ready&&!window.Art.buildable(g.level,p))return false;if(p.x<28||p.x>972||p.y<28||p.y>572)return false;if(pathDistance(p,g.routes)<44)return false;if(!window.Art?.ready&&g.decor.some(d=>Math.hypot(p.x-d.x,p.y-d.y)<d.r+19))return false;if(g.debris.some(d=>Math.hypot(p.x-d.x,p.y-d.y)<62))return false;if(!window.Art?.ready&&g.level===4&&![[180,260,140],[390,180,125],[540,395,125],[730,350,135],[920,230,105]].some(([x,y,r])=>Math.hypot(p.x-x,p.y-y)<r-24))return false;return true;}
const buildSiteCache=new Map();
function createBuildSites(){const key=g.level+':'+!!window.Art?.ready+':'+g.debris.map(d=>d.x+','+d.y).join(';');if(buildSiteCache.has(key))return buildSiteCache.get(key);const candidates=[];for(let y=36;y<=564;y+=12)for(let x=36;x<=964;x+=12){const p={x,y};if(terrainValid(p))candidates.push({...p,score:Math.abs(pathDistance(p,g.routes)-75)});}candidates.sort((a,b)=>a.score-b.score||a.y-b.y||a.x-b.x);const sites=[];for(const p of candidates)if(sites.every(q=>Math.hypot((p.x-q.x)/54,(p.y-q.y)/84)>=1))sites.push(p);buildSiteCache.set(key,sites);return sites;}
function nearestSite(p){return g.buildSites.filter(q=>Math.hypot(q.x-p.x,q.y-p.y)<=29).sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y))[0];}
function valid(p){return g.buildSites.some(q=>q.x===p.x&&q.y===p.y)&&terrainValid(p)&&!g.towers.some(t=>Math.hypot(p.x-t.x,p.y-t.y)<43);}
function drawBuildSites(c){if(g.tool===null)return;for(const p of g.buildSites){if(!valid(p))continue;const active=g.mouse&&Math.hypot(g.mouse.x-p.x,g.mouse.y-p.y)<2;c.save();c.translate(p.x,p.y);c.scale(1,.55);c.lineWidth=active?3:2;circle(c,0,0,22,active?'#a1ffda88':'#102e37bb',active?'#e3fff3':'#a1ffdadb');c.strokeStyle='#baffdf';c.beginPath();c.moveTo(-7,0);c.lineTo(7,0);c.moveTo(0,-7);c.lineTo(0,7);c.stroke();c.restore();}}
function act(p){if(g.ended)return;const tower=[...g.towers].sort((a,b)=>b.y-a.y).find(t=>Math.abs(t.x-p.x)<33&&p.y>=t.y-68&&p.y<=t.y+14);if(tower){g.selected=tower;g.tool=null;updateUI();return;}const debris=g.debris.find(d=>Math.hypot(d.x-p.x,d.y-p.y)<48);if(debris){if(g.cash<75){toast('Clearing rubble costs $75.');return;}g.cash-=75;g.debris=g.debris.filter(d=>d!==debris);g.buildSites=createBuildSites();toast('Rubble cleared. New building space available.');updateUI();return;}if(g.tool===null){g.selected=null;updateUI();return;}const site=nearestSite(p);if(!site){toast('Choose one of the highlighted build pads.');return;}p=site;const t=types[g.tool];if(!valid(p)){toast('This build pad is occupied or blocked.');return;}if(g.cash<t.cost){toast('Not enough space dollars for this tower.');return;}g.cash-=t.cost;g.towers.push({x:p.x,y:p.y,type:g.tool,level:1,cooldown:0,angle:-Math.PI/2,spent:t.cost});g.tool=null;g.selected=null;updateUI();}
function updateUI(){if(!g)return;$('#cash').textContent='$'+g.cash;$('#health').textContent=g.hp;$('#wave').textContent=`${g.wave} / ${g.total}`;$('#message').textContent=g.message;$('#phase').textContent=g.paused?'PAUSED':g.running?'WAVE INCOMING':'BUILD PHASE';document.querySelectorAll('.shop-item').forEach((b,j)=>{b.classList.toggle('active',g.tool===j);});$('#launch').disabled=g.ended||g.wave>=g.total||g.queue.length>0;$('#launch').textContent=g.wave>=g.total?'Final wave':g.queue.length?'Spawning wave '+g.wave:g.running?'Send wave '+(g.wave+1)+' early':`Wave ${g.wave+1} · ${Math.ceil(g.nextWaveIn)}s`;
const d=$('#details'),t=g.selected;const detailKey=t?g.towers.indexOf(t)+':'+t.level:'brief';if(d.dataset.key===detailKey){if(t){const cost=Math.round(types[t.type].cost*(.7+t.level*.35));$('#upgrade').disabled=t.level>=3||g.cash<cost;}return;}d.dataset.key=detailKey;if(t){const spec=types[t.type],cost=Math.round(spec.cost*(.7+t.level*.35));d.innerHTML=`<span class="eyebrow">SELECTED TOWER</span><h3>${spec.name} · Mk ${t.level}</h3><p class="help">${spec.note}<br>Damage ${Math.round(spec.damage*(1+(t.level-1)*.65))} · Range ${spec.range+(t.level-1)*15}</p><div class="selected-actions"><button class="primary" id="upgrade" ${t.level>=3||g.cash<cost?'disabled':''}>${t.level>=3?'Fully upgraded':'Upgrade · $'+cost}</button><button id="sell">Sell · $${Math.floor(t.spent*.7)}</button></div>`;$('#upgrade').onclick=()=>{if(t.level>=3||g.cash<cost)return;g.cash-=cost;t.spent+=cost;t.level++;updateUI();};$('#sell').onclick=()=>{g.cash+=Math.floor(t.spent*.7);g.towers=g.towers.filter(a=>a!==t);g.selected=null;updateUI();};}else{d.innerHTML=`<span class="eyebrow">TOWER UPGRADES</span><h3>Select a placed tower</h3><p class="help">Click its body or base to upgrade or sell. Select a tower to reveal build pads. Keys 1–9 and 0 select towers; Space sends the next wave; P pauses.</p>${g.level>=2?'<p class="help">Flak, Zapper and Rockets can hit aircraft.</p>':''}`;}}
function launch(){if(!g||g.paused||g.queue.length||g.ended||g.wave>=g.total)return;g.wave++;g.running=true;g.nextWaveIn=null;g.spawn=0;g.queue=waveRoster(g.level+1,g.wave);g.message=`Wave ${g.wave}: ${g.queue.length} hostiles${g.queue.some(id=>enemyCatalog[id].group==='air')?' • aircraft detected':''}${g.level===7?' • '+(g.wave%2?'north':'south')+' gate active':''}.`;updateUI();}
function spawn(kind){const def=enemyCatalog[kind];if(!def)throw new Error('Unknown enemy '+kind);const mult=1+(g.wave-1)*.25+g.level*.13,ri=g.level===7?(g.wave-1)%2:g.queue.length%g.routes.length,ground=g.routes[ri],flying=def.group==='air',route=flying?[{...ground[0]},{...ground.at(-1)}]:ground,enemy={kind,flying,group:def.group,armour:def.armour||0,size:def.size,baseDamage:def.hits||1,hp:def.hp*mult,max:def.hp*mult,speed:def.speed,reward:def.reward,d:0,route,slow:0,x:route[0].x,y:route[0].y,angle:0};g.enemies.push(enemy);introduce(enemy);}

function tick(dt){if(g.paused||g.ended)return;g.time+=dt;if(!g.running&&g.nextWaveIn!==null&&g.wave<g.total){g.nextWaveIn=Math.max(0,g.nextWaveIn-dt/g.speed);if(g.nextWaveIn===0)launch();}g.heavyCooldown=Math.max(0,g.heavyCooldown-dt);if(g.intro){g.introRemaining-=dt/g.speed;if(g.introRemaining<=0)nextIntro();}if(g.running){g.spawn-=dt;if(g.queue.length&&g.spawn<=0){const heavy=isHeavyEnemy(g.queue[0]),busy=g.enemies.some(e=>e.hp>0&&!e.escaped&&isHeavyEnemy(e.kind));if(!heavy||!busy&&g.heavyCooldown<=0){spawn(g.queue.shift());g.spawn=heavy?2.5:.8;}}}
for(const e of g.enemies){if(e.hp<=0)continue;if(e.poisonTime>0){const active=Math.min(dt,e.poisonTime);e.poisonTime-=active;hurt(e,e.poisonDps*active,'#94f16b');if(e.hp<=0)continue;}e.slow=Math.max(0,e.slow-dt);e.d+=e.speed*dt*(e.slow>0?.5:1);const p=sample(e.route,e.d);if(p)Object.assign(e,p);else{e.escaped=true;if(isHeavyEnemy(e.kind))g.heavyCooldown=3;g.hp=Math.max(0,g.hp-(e.baseDamage||1));}}
g.enemies=g.enemies.filter(e=>!e.escaped&&e.hp>0);if(g.hp<=0){finish(false);return;}advanceAmmunition(dt);
for(const t of g.towers){t.cooldown-=dt;const spec=types[t.type],range=spec.range+(t.level-1)*15;const inRange=e=>e.hp>0&&(t.type===4?e.flying:spec.air||!e.flying)&&Math.hypot(e.x-t.x,e.y-t.y)<=range;const candidates=g.enemies.filter(inRange);const target=candidates.sort((a,b)=>remaining(a)-remaining(b))[0];if(!target)continue;t.angle=Math.atan2(target.y-t.y,target.x-t.x);if(t.cooldown>0)continue;t.cooldown=spec.rate/(1+(t.level-1)*.12);fireTower(t,target);}

g.enemies=g.enemies.filter(e=>e.hp>0);g.effects.forEach(s=>s.life-=dt);g.effects=g.effects.filter(s=>s.life>0);g.rewards.forEach(r=>r.life-=dt/g.speed);g.rewards=g.rewards.filter(r=>r.life>0);if(g.running&&!g.queue.length&&!g.enemies.length&&!g.shots.some(s=>s.flight)){g.running=false;g.nextWaveIn=8;if(g.wave===g.total){finish(true);return;}g.message=`Wave cleared. ${g.level===7?'Next route: '+(g.wave%2?'south':'north')+' gate. ':''}Next wave in 8 seconds. Press Space to send it now.`;}updateUI();}
function hurt(e,damage,color){if(e.hp<=0||e.rewarded)return;e.hp-=damage;if(e.hp<=0){if(isHeavyEnemy(e.kind))g.heavyCooldown=3;e.rewarded=true;g.cash+=e.reward;g.kills++;g.rewards.push({x:e.x,y:e.y,amount:e.reward,life:.85});g.effects.push({x:e.x,y:e.y,color,life:.4});}}
function remaining(e){const r=e.route;if(r.total===undefined){r.total=0;for(let i=1;i<r.length;i++)r.total+=Math.hypot(r[i].x-r[i-1].x,r[i].y-r[i-1].y);}return r.total-e.d;}
function modal(title,text,actions,starCount=null,enemyKind=null){$('.overlay')?.remove();const wrap=document.createElement('div');wrap.className='overlay';wrap.innerHTML=`<div class="modal" role="dialog" aria-modal="true" aria-label="${title}"><span class="tag">TOWERVERSE</span><h2>${title}</h2>${enemyKind?'<canvas class="enemy-portrait" width="560" height="320" role="img" aria-label="'+title+' artwork"></canvas>':''}${starCount!==null?'<div class="stars">'+stars(starCount)+'</div>':''}<p>${text}</p><div class="actions"></div></div>`;for(const [label,fn]of actions){const b=document.createElement('button');b.textContent=label;b.className='primary';b.onclick=()=>{wrap.remove();fn();};wrap.querySelector('.actions').append(b);}document.body.append(wrap);if(enemyKind&&window.Art?.ready){const art=window.Art,f=art.frameFor(enemyKind);if(f){const cv=wrap.querySelector('.enemy-portrait'),ctx=cv.getContext('2d'),scale=Math.min(500/f.w,290/f.h),w=f.w*scale,h=f.h*scale;ctx.drawImage(f.image,f.x,f.y,f.w,f.h,(560-w)/2,(320-h)/2,w,h);}}wrap.querySelector('button').focus();}
function finish(won){g.ended=true;const i=g.level,n=won?(g.hp===20?3:g.hp>=10?2:1):0;if(won){progress[i]=Math.max(progress[i],n);save();}modal(won?'Planet secured':'Base lost',won?`${g.hp} / 20 base health · ${g.kills} enemies defeated.${i<9?' The next planet is unlocked.':' You have completed the campaign!'}`:'Reposition your towers and try again. Upgrades help against armoured enemies.',[['Campaign',menu],['Retry',()=>start(i)],...(won&&i<9?[['Next planet',()=>start(i+1)]]:[])],won?n:null);}
function loop(now){if(!g)return;const dt=Math.min((now-previous)/1000,.05);previous=now;tick(dt*g.speed);draw();frame=requestAnimationFrame(loop);}
function circle(c,x,y,r,fill,stroke){c.beginPath();c.arc(x,y,r,0,Math.PI*2);if(fill){c.fillStyle=fill;c.fill();}if(stroke){c.strokeStyle=stroke;c.stroke();}}
function draw(){if(!g)return;const c=$('canvas').getContext('2d'),l=levels[g.level];c.clearRect(0,0,1000,600);if(window.Art?.ready){drawIllustrated(c);return;}c.fillStyle=l[2];c.fillRect(0,0,1000,600);let bg=c.createRadialGradient(420,250,20,500,300,650);bg.addColorStop(0,l[3]+'18');bg.addColorStop(1,'#00000055');c.fillStyle=bg;c.fillRect(0,0,1000,600);
c.strokeStyle='#ffffff06';c.lineWidth=1;for(let x=0;x<1000;x+=40){c.beginPath();c.moveTo(x,0);c.lineTo(x,600);c.stroke();}for(let y=0;y<600;y+=40){c.beginPath();c.moveTo(0,y);c.lineTo(1000,y);c.stroke();}
if(g.level===4)for(const[x,y,r]of[[180,260,140],[390,180,125],[540,395,125],[730,350,135],[920,230,105]]){circle(c,x,y,r,'#527d3d','#8eaa55');c.strokeStyle='#a5b97755';for(let a=0;a<6.3;a+=.65){c.beginPath();c.moveTo(x,y);c.lineTo(x+Math.cos(a)*r,y+Math.sin(a)*r);c.stroke();}}
g.routes.forEach((r,j)=>{c.lineCap='round';c.lineJoin='round';c.beginPath();r.forEach((p,k)=>k?c.lineTo(p.x,p.y):c.moveTo(p.x,p.y));const active=g.level!==7||j===(g.running?(g.wave-1)%2:g.wave%2);c.lineWidth=64;c.strokeStyle='#00000045';c.stroke();c.lineWidth=49;c.strokeStyle=active?l[4]:'#786b5a';c.stroke();c.lineWidth=2;c.setLineDash([3,12]);c.strokeStyle=active?'#ffffff32':'#ffffff10';c.stroke();c.setLineDash([]);if(g.level===7){const p=r[2];c.fillStyle=active?'#9eeac8':'#d77575';c.fillRect(p.x-30,p.y-35,12,70);c.fillRect(p.x+18,p.y-35,12,70);}});
if(g.level===5){c.save();c.translate(500,300);c.rotate(.88);c.fillStyle='#9bb4c3';c.fillRect(-68,-25,136,50);c.strokeStyle='#405769';c.lineWidth=6;c.strokeRect(-68,-25,136,50);c.restore();}
for(const d of g.decor){if(!window.Art?.ready&&g.level===4&&![[180,260,140],[390,180,125],[540,395,125],[730,350,135],[920,230,105]].some(([x,y,r])=>Math.hypot(d.x-x,d.y-y)<r-30))continue;circle(c,d.x+3,d.y+5,d.r,'#00000027');if([1,3,8,9].includes(g.level)){c.fillStyle=l[3]+'80';c.beginPath();c.moveTo(d.x,d.y-d.r);c.lineTo(d.x+d.r*.7,d.y+d.r);c.lineTo(d.x-d.r*.8,d.y+d.r*.7);c.closePath();c.fill();c.fillStyle='#ffffff20';c.fillRect(d.x-2,d.y-d.r*.5,3,d.r);}else{circle(c,d.x,d.y,d.r,l[3]+'55');circle(c,d.x-3,d.y-4,d.r*.6,l[3]+'66');}}
for(const d of g.debris){c.fillStyle='#626e6b';c.fillRect(d.x-28,d.y-23,36,35);c.fillStyle='#a6b0a5';c.fillRect(d.x,d.y-10,27,31);c.fillStyle='#d9d8ab';c.font='bold 14px system-ui';c.textAlign='center';c.fillText('CLEAR · 75',d.x,d.y+47);}
const end=g.routes[0].at(-1);circle(c,end.x,end.y,33,'#172c3c','#84d3e7');circle(c,end.x,end.y,23,'#2c5364','#9ce7f5');circle(c,end.x,end.y,12,'#b6f9f4');c.fillStyle='#edffff';c.font='bold 11px system-ui';c.textAlign='center';c.fillText('BASE',Math.min(970,end.x),end.y+50);
for(const r of g.routes){const p=r[0];circle(c,Math.max(15,Math.min(985,p.x)),Math.max(15,Math.min(585,p.y)),12,'#182f3d','#9eeac8');}
drawBuildSites(c);const t=g.selected,hover=g.tool!==null&&g.mouse?g.mouse:null;if(t||hover){const q=t||hover,spec=types[t?t.type:g.tool],r=spec.range+(t?(t.level-1)*15:0);circle(c,q.x,q.y,r,hover?(valid(q)&&g.cash>=spec.cost?'#9eeac817':'#ff77771c'):'#b6eaff15',hover?(valid(q)?'#9eeac888':'#ff777788'):'#b6eaff66');}
for(const t of g.towers){drawTower(c,t);towerBar(c,t);}if(hover){c.globalAlpha=.6;drawTower(c,{...hover,type:g.tool,angle:-Math.PI/2,level:1});c.globalAlpha=1;}
for(const e of g.enemies){c.save();c.translate(e.x,e.y);c.rotate(e.angle);const boss=e.kind==='boss',r=boss?23:e.kind==='armour'?15:11;circle(c,2,4,r,'#0005');if(e.flying){c.fillStyle='#e8beff';c.beginPath();c.moveTo(18,0);c.lineTo(-12,-16);c.lineTo(-5,0);c.lineTo(-12,16);c.closePath();c.fill();circle(c,0,0,5,'#8a568e');}else{c.fillStyle=boss?'#e27088':e.kind==='armour'?'#9caabc':e.kind==='runner'?'#eacb82':'#d98594';c.beginPath();for(let j=0;j<6;j++){const a=j*Math.PI/3;c.lineTo(Math.cos(a)*r,Math.sin(a)*r);}c.closePath();c.fill();circle(c,r*.3,0,r*.3,'#182438');for(const s of[-1,1]){c.strokeStyle='#263843';c.lineWidth=3;c.beginPath();c.moveTo(-r/2,s*r/2);c.lineTo(-r,s*(r+4));c.stroke();}}c.restore();c.fillStyle='#14242c';c.fillRect(e.x-18,e.y-rSize(e)-10,36,4);c.fillStyle=e.slow>0?'#80d4ff':'#b8e5b1';c.fillRect(e.x-18,e.y-rSize(e)-10,36*Math.max(0,e.hp/e.max),4);}
drawAmmunition(c);for(const e of g.effects){circle(c,e.x,e.y,(.4-e.life)*60,null,e.color);}
if(g.paused){c.fillStyle='#050e1880';c.fillRect(0,0,1000,600);c.fillStyle='#edf7ff';c.font='bold 38px system-ui';c.textAlign='center';c.fillText('PAUSED',500,300);}}
function rSize(e){return e.kind==='boss'?23:16;}
function drawTower(c,t){if(window.Art?.ready){window.Art.tower(c,t);return;}const spec=types[t.type];c.save();c.translate(t.x,t.y);circle(c,3,5,21,'#0005');circle(c,0,0,20,'#1c303d',spec.color);circle(c,0,0,14,'#344b57');c.rotate(t.angle);c.fillStyle=spec.color;c.fillRect(0,-5,27,10);c.fillStyle='#13232d';c.fillRect(17,-3,9,6);circle(c,0,0,8,spec.color);c.restore();for(let i=0;i<t.level;i++)circle(c,t.x-6+(i*6),t.y+26,2,spec.color);}
function handleKey(e){if(!g||g.ended||$('.overlay')||e.repeat||e.ctrlKey||e.metaKey||e.altKey||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)||document.activeElement.isContentEditable)return;if(e.code==='Space'||e.key==='Enter'){e.preventDefault();launch();return;}if(e.code==='Escape'){g.tool=null;g.selected=null;updateUI();}if(e.code==='KeyP'){e.preventDefault();$('#pause').onclick();}const digit=/^(?:Digit|Numpad)([0-9])$/.exec(e.code);if(digit){e.preventDefault();g.tool=digit[1]==='0'?9:Number(digit[1])-1;g.selected=null;g.mouse=null;updateUI();}}
window.addEventListener('keydown',handleKey);
document.addEventListener('visibilitychange',()=>{if(document.hidden&&g&&!g.ended){g.paused=true;$('#pause').textContent='Resume';}});
