function resolveShot(s){const target=s.target,t=s.source,spec=types[s.type],damage=spec.damage*(1+(s.level-1)*.65);let victims=[];if(s.type===1||s.type===9){const radius=s.type===9?75:64;victims=g.enemies.filter(e=>e.hp>0&&!e.escaped&&!!e.flying===!!target.flying&&Math.hypot(e.x-target.x,e.y-target.y)<radius);}else if(s.type===5){victims=g.enemies.filter(e=>e.hp>0&&!e.flying&&Math.hypot(e.x-t.x,e.y-t.y)<=spec.range+(s.level-1)*15&&Math.cos(Math.atan2(e.y-t.y,e.x-t.x)-t.angle)>.68);}else if(s.type===7&&target.hp>0&&!target.escaped){victims=[target];while(victims.length<3){const p=victims.at(-1),next=g.enemies.filter(e=>e.hp>0&&!e.escaped&&!victims.includes(e)&&Math.hypot(e.x-p.x,e.y-p.y)<100).sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y))[0];if(!next)break;victims.push(next);}}else if(target.hp>0&&!target.escaped)victims=[target];s.chain=[{x:s.x,y:s.y},...victims.map(targetPoint)];for(let i=0;i<victims.length;i++){const e=victims[i],armour=s.type===3?1:(1-(e.armour||0));hurt(e,damage*armour*(s.type===7?Math.pow(.78,i):1),s.color);if(s.type===2)e.slow=2.1;if(s.type===8&&e.hp>0){e.poisonTime=3.5;e.poisonDps=12*(1+(s.level-1)*.65);}}g.impacts.push({type:s.type,x:s.tx,y:s.ty,groundY:target.y,age:0,duration:ammunitionSpec[s.type].impact,seed:g.time*13+s.x,color:s.color});if(g.impacts.length>150)g.impacts.shift();}
